"""One exact whole-shard observation; no profiler, transport or Popen replacement."""
import argparse,base64,collections,hashlib,inspect,json,os,runpy,signal,subprocess,sys,time,zlib
from pathlib import Path
ENCODED=''
PAYLOAD_SHA='b2efae28c85de396f405f6e0a8e4031c2d357bca62aeab1998eebb9d620689f8'
def digest(v):return hashlib.sha256(json.dumps(v,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def payload():
    raw=zlib.decompress(base64.b64decode(ENCODED,validate=True));assert hashlib.sha256(raw).hexdigest()==PAYLOAD_SHA and len(raw)<4*1024*1024
    return json.loads(raw)
def save(path,data):path.write_text(json.dumps(data,indent=2)+'\n',encoding='utf-8')
def self_test():
    p=payload();assert len(p['ids'])==len(set(p['ids']))==1187 and digest(p['ids'])==p['ids_sha256']
    assert json.loads(json.dumps(p['ids'],ensure_ascii=True))==p['ids']
    canaries=[r'C:\one\two',r'C:\\one\\two','literal\\n','real\nnewline','quote"Δ']
    assert json.loads(json.dumps(canaries,ensure_ascii=True))==canaries
    assert len(p['constraints'])==88 and p['shard']==4 and p['shards']==7
    return {'status':'EXACT_IDS_AND_BACKSLASH_ROUNDTRIP_PASS','count':len(p['ids']),'payload_sha256':PAYLOAD_SHA}
def proof(repo):
    sys.path.insert(0,str(repo))
    from scripts import check_launch_change_scope as g,scope_reconstruction as h
    counts={n:len(h._context_fields(inspect.unwrap(getattr(g,n)))) for n in h.NAMES}
    assert counts=={'_nfl_odds_timing_base_source':393,'_nfl_odds_base_source':512}
    assert h.MAX_CONTEXT_FIELDS==512
    # A synthetic immutable graph exactly at the limit is supported; adding one
    # referenced field rejects. No live namespace or validation is monkeypatched.
    def synthetic(n):
        ns={f'VALUE_{i}':i for i in range(n)}
        exec('def subject(source):\n    return source if ('+'+'.join(ns)+') >= 0 else source\n',ns)
        return ns['subject']
    assert len(h._context_fields(synthetic(509)))==512
    assert h._context_fields(synthetic(510)) is None
    source=(repo/g.GUARD_PATH).read_bytes().replace(b'\r\n',b'\n')
    binding=json.loads((repo/'docs/paid-launch/nfl-pdf-seven-fixture-binding-v1.json').read_bytes())
    previous=g._nfl_pdf_fixture_base_source(source)
    assert hashlib.sha256(previous).hexdigest()==binding['previous_guard_sha256']
    assert hashlib.sha256((repo/'scripts/scope_reconstruction.py').read_bytes()).hexdigest()==payload()['helper_sha256']
    return dict(context_fields=counts,limit=512,at_limit='SUPPORTED',one_over='REJECTED',predecessor_sha256=hashlib.sha256(previous).hexdigest(),immutable_helper_unchanged=True)
def main():
    a=argparse.ArgumentParser();a.add_argument('--self-test',action='store_true');a.add_argument('--constraints',type=Path);a.add_argument('--repo',type=Path);a.add_argument('--output',type=Path);a.add_argument('--collect-only',action='store_true');args=a.parse_args();p=payload()
    if args.self_test:print(json.dumps(self_test()));return 0
    if args.constraints:args.constraints.write_text('\n'.join(p['constraints'])+'\n');return 0
    repo=args.repo.resolve();out=args.output.resolve();out.mkdir(parents=True,exist_ok=False);os.chdir(repo);sys.path.insert(0,str(repo))
    assert subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()==p['head']
    assert subprocess.check_output(['git','rev-parse','HEAD^{tree}'],text=True).strip()==p['tree']
    assert subprocess.check_output(['git','rev-parse','--is-shallow-repository'],text=True).strip()=='true'
    if not args.collect_only:
        assert os.environ.get('ImageVersion')==p['image'] and sys.version.split()[0]==p['python']
    pre=proof(repo);save(out/'context-proof.json',pre)
    import pytest
    runner=runpy.run_path(str(repo/'scripts/run_ci_tests.py'),run_name='original_runner_targeted_observation')
    shard=runner['FileShard'](3,7,runner['load_profile'](repo/'scripts/ci_test_file_costs_v1.json'),out/'full-suite-4-assignment.json',repo)
    start=time.perf_counter();events=(out/'progress.jsonl').open('x',encoding='utf-8',buffering=1);phases=[];fixtures=[];outcomes=[]
    def emit(kind,**v):events.write(json.dumps(dict(kind=kind,elapsed=time.perf_counter()-start,**v))+'\n');events.flush()
    class Observe:
        @pytest.hookimpl(trylast=True)
        def pytest_collection_modifyitems(self,session,config,items):
            assert [i.nodeid for i in items]==p['ids']
            m=shard.manifest;assert m['collected_count']==7889 and m['assignment_sha256']==p['assignment_sha256'] and m['profile_sha256']==p['profile_sha256']
            assert config.option.basetemp is None;emit('exact_assignment_verified',count=len(items),sha256=digest(p['ids']))
        @pytest.hookimpl(hookwrapper=True)
        def pytest_collection(self,session):
            t=time.perf_counter();yield;phases.append(dict(phase='collection',seconds=time.perf_counter()-t))
        @pytest.hookimpl(hookwrapper=True)
        def pytest_fixture_setup(self,fixturedef,request):
            t=time.perf_counter();yield;fixtures.append(dict(name=fixturedef.argname,scope=fixturedef.scope,node=request.node.nodeid,seconds=time.perf_counter()-t))
        @pytest.hookimpl(hookwrapper=True)
        def pytest_runtest_setup(self,item):
            t=time.perf_counter();yield;phases.append(dict(phase='setup',node=item.nodeid,seconds=time.perf_counter()-t))
        @pytest.hookimpl(hookwrapper=True)
        def pytest_runtest_call(self,item):
            t=time.perf_counter();yield;phases.append(dict(phase='call',node=item.nodeid,seconds=time.perf_counter()-t))
        @pytest.hookimpl(hookwrapper=True)
        def pytest_runtest_teardown(self,item):
            t=time.perf_counter();yield;phases.append(dict(phase='teardown',node=item.nodeid,seconds=time.perf_counter()-t))
        def pytest_runtest_logreport(self,report):
            if report.when=='call' or (report.when=='setup' and report.outcome!='passed'):
                outcomes.append(dict(nodeid=report.nodeid,when=report.when,outcome=report.outcome));emit('outcome',**outcomes[-1])
    class Budget(BaseException):pass
    def alarm(*_):raise Budget()
    if hasattr(signal,'SIGALRM'):signal.signal(signal.SIGALRM,alarm);signal.alarm(1660)
    interrupted=False;code=124
    options=['-v','tests','--durations=30','--junitxml='+str(out/'full-suite-4.xml')]
    if args.collect_only:options.append('--collect-only')
    try:code=int(pytest.main(options,plugins=[shard,Observe()]))
    except Budget:interrupted=True;emit('INTERRUPTED_BUDGET')
    finally:
        if hasattr(signal,'SIGALRM'):signal.alarm(0)
        report_started=time.perf_counter();code=shard.finish(code)
        from scripts import check_launch_change_scope as g
        caches={n:dict(hits=getattr(g,n).reconstruction_memo.hits,misses=getattr(g,n).reconstruction_memo.misses,fields=getattr(g,n).reconstruction_context_fields,retained_bytes=getattr(g,n).reconstruction_memo.retained_bytes) for n in ('_nfl_odds_timing_base_source','_nfl_odds_base_source') if hasattr(getattr(g,n),'reconstruction_memo')}
        save(out/'receipt.json',dict(status='INTERRUPTED' if interrupted else 'COMPLETED_TARGETED_ONLY',exit_code=code,head=p['head'],tree=p['tree'],elapsed_seconds=time.perf_counter()-start,phases=phases,fixtures=fixtures,outcomes=outcomes,complete=len(outcomes)==len(p['ids']),caches=caches,context_proof=pre,default_temp=True,profiler=False,network_or_popen_replacement=False,collect_only=args.collect_only,limitations='Observation hooks only; fixture timings overlap test phases. Job setup/upload/cleanup measured from Actions steps separately. Not full release coverage.'))
        emit('report_written',seconds=time.perf_counter()-report_started);events.close()
    return code
if __name__=='__main__':raise SystemExit(main())
